 * @param {Array<() => Promise>} tasks - Promise 任务数组
 * @returns {Promise<Array>} 所有任务的结果数组
 */
async function serialPromise(tasks) {
  const results = [];

  for (const task of tasks) {
    try {
      const result = await task();
      results.push(result);
    } catch (error) {
      console.error("Task failed:", error);
      throw error;
    }
  }

  return results;
}

