 ## 1. 中间件基本概念 

Koa 的中间件是一个函数，它接收两个参数：
- `ctx`：上下文对象，包含请求和响应信息
- `next`：下一个中间件函数

### 1.1. 基本结构

```javascript
const Koa = require('koa');
const app = new Koa();

app.use(async (ctx, next) => {
    // 中间件逻辑
    await next();
});
```

### 1.2. 洋葱模型

```javascript
app.use(async (ctx, next) => {
    console.log('1. 进入第一层');
    await next();
    console.log('6. 离开第一层');
});

app.use(async (ctx, next) => {
    console.log('2. 进入第二层');
    await next();
    console.log('5. 离开第二层');
});

app.use(async (ctx, next) => {
    console.log('3. 进入第三层');
    ctx.body = 'Hello World';
    console.log('4. 离开第三层');
});
```

输出顺序：
```
1. 进入第一层
2. 进入第二层
3. 进入第三层
4. 离开第三层
5. 离开第二层
6. 离开第一层
```

## 2. 常用中间件类型

### 2.1. 错误处理中间件

```javascript
app.use(async (ctx, next) => {
    try {
        await next();
    } catch (err) {
        ctx.status = err.status || 500;
        ctx.body = {
            code: ctx.status,
            message: err.message,
            error: process.env.NODE_ENV === 'development' ? err.stack : undefined
        };
        // 触发应用级错误事件
        ctx.app.emit('error', err, ctx);
    }
});
```

### 2.2. 日志中间件

```javascript
app.use(async (ctx, next) => {
    const start = Date.now();

    // 请求日志
    console.log(`--> ${ctx.method} ${ctx.url}`);

    await next();

    // 响应日志
    const ms = Date.now() - start;
    console.log(`<-- ${ctx.method} ${ctx.url} ${ctx.status} ${ms}ms`);
});
```

### 2.3. 认证中间件

```javascript
const jwt = require('jsonwebtoken');

const auth = async (ctx, next) => {
    try {
        const token = ctx.header.authorization?.split(' ')[1];
        if (!token) {
            ctx.throw(401, '未提供认证令牌');
        }

        const decoded = jwt.verify(token, process.env.JWT_SECRET);
        ctx.state.user = decoded;

        await next();
    } catch (err) {
        ctx.throw(401, '认证失败');
    }
};

// 使用中间件
app.use(auth);
```

### 2.4. 响应格式化中间件

```javascript
app.use(async (ctx, next) => {
    await next();

    // 统一响应格式
    if (ctx.body) {
        ctx.body = {
            code: ctx.status === 200 ? 0 : ctx.status,
            data: ctx.body,
            message: ctx.message || 'success',
            timestamp: new Date().toISOString()
        };
    }
});
```

## 3. 高级中间件模式

### 3.1. 条件中间件

```javascript
const unless = require('koa-unless');

const authMiddleware = async (ctx, next) => {
    // 认证逻辑
    await next();
};

// 添加除外路径
authMiddleware.unless = unless;

app.use(authMiddleware.unless({
    path: [/^\/public/, '/login', '/register']
}));
```

### 3.2. 组合中间件

```javascript hl:1
const compose = require('koa-compose');

const middlewares = compose([
    async (ctx, next) => {
        // 中间件1
        await next();
    },
    async (ctx, next) => {
        // 中间件2
        await next();
    }
]);

app.use(middlewares);
```

### 3.3. 参数化中间件

```javascript
const rateLimit = (options = {}) => {
    const { interval = 60000, max = 100 } = options;
    const store = new Map();

    return async (ctx, next) => {
        const key = ctx.ip;
        const now = Date.now();
        const requests = store.get(key) || [];

        // 清理过期请求记录
        const validRequests = requests.filter(time => now - time < interval);

        if (validRequests.length >= max) {
            ctx.throw(429, '请求过于频繁');
        }

        validRequests.push(now);
        store.set(key, validRequests);

        await next();
    };
};

// 使用中间件
app.use(rateLimit({ interval: 60000, max: 100 }));
```

