# Node.js 中的通信方式都有哪些

`#nodejs` 


## 目录
<!-- toc -->
 ## 1. 总结 

- child_process：
	- 适用于`父子进程`通信
- cluster：
	- 适用于`主从架构的多进程应用`
- Socket：
	- 适用于`跨机器`的进程通信 
- 消息队列：
	- 适用于解耦的异步通信 （redis）
- 共享**内存**：
	- 适用于高性能数据共享（`worker_threads`）
- HTTP / HTTPS：
	- 适用于 `RESTful` 服务通信
- WebSocket：
	- 适用于实时**双向通信**
- 进程管理：
	- 适用于复杂的多进程应用

> 下面展开聊

## 2. child_process 子进程通信

- `spawn` 方式
- `fork` 方式

```javascript hl:1,19
// 1.1 spawn 方式
const { spawn } = require('child_process');

// 父进程
const child = spawn('node', ['child.js']);

child.stdout.on('data', (data) => {
    console.log('子进程输出：', data.toString());
});

child.stderr.on('data', (data) => {
    console.error('子进程错误：', data.toString());
});

child.on('close', (code) => {
    console.log(`子进程退出，退出码 ${code}`);
});

// 1.2 fork 方式
const { fork } = require('child_process');

// 父进程 (parent.js)
const child = fork('./child.js');

// 发送消息给子进程
child.send({ hello: 'world' });

// 接收子进程消息
child.on('message', (message) => {
    console.log('收到子进程消息:', message);
});

// 子进程 (child.js)
process.on('message', (message) => {
    console.log('收到父进程消息:', message);
    // 回复父进程
    process.send({ received: true });
});
```

## 3. cluster **集群模式**通信

```javascript hl:34,39
const cluster = require('cluster');
const http = require('http');
const numCPUs = require('os').cpus().length;

if (cluster.isMaster) {
    // 主进程代码
    console.log(`主进程 ${process.pid} 正在运行`);

    // 生成工作进程
    for (let i = 0; i < numCPUs; i++) {
        const worker = cluster.fork();

        // 主进程发送消息给工作进程
        worker.send({ type: 'hello', from: 'master' });

        // 接收工作进程消息
        worker.on('message', (message) => {
            console.log(`主进程收到来自工作进程 ${worker.id} 的消息:`, message);
        });
    }

    // 监听工作进程退出
    cluster.on('exit', (worker, code, signal) => {
        console.log(`工作进程 ${worker.process.pid} 已退出`);
    });
} else {
    // 工作进程代码
    http.createServer((req, res) => {
        res.writeHead(200);
        res.end('你好，世界\n');
    }).listen(8000);

    // 工作进程接收消息
    process.on('message', (message) => {
        console.log(`工作进程 ${process.pid} 收到消息:`, message);
    });

    // 工作进程发送消息给主进程
    process.send({ type: 'ready', pid: process.pid });
}
```

## 4. Socket 通信

```javascript
// 3.1 TCP Socket
const net = require('net');

// TCP 服务器
const server = net.createServer((socket) => {
    socket.on('data', (data) => {
        console.log('收到数据:', data.toString());
        socket.write('服务器已收到消息');
    });
});

server.listen(8080, () => {
    console.log('TCP 服务器启动在端口 8080');
});

// TCP 客户端
