    <template `#default>`
      <AsyncComponent />
    </template>
    <template `#fallback>`
      <LoadingComponent />
    </template>
  </Suspense>
</template>

<script setup>
import { onErrorCaptured } from 'vue'

// 捕获异步组件错误
onErrorCaptured((error, instance, info) => {
  console.error('捕获到错误:', error)
  // 返回 false 阻止错误继续传播
  return false
})

const onPending = () => {
  console.log('组件加载中...')
}

const onResolve = () => {
  console.log('组件加载完成')
}

const onFallback = () => {
  console.log('显示 fallback 内容')
}
</script>
```

