    if (isQuoted) {
      advanceBy(1); // 跳过引号
      const endQuoteIndex = context.source.indexOf(quote); // 查找引号结束位置
      if (endQuoteIndex > -1) {
        value = context.source.slice(0, endQuoteIndex); // 获取属性值
        advanceBy(value.length); // 前进到属性值之后
        advanceBy(1); // 跳过引号
      } else {
        console.error("缺少引号");
      }
    } else {
      const match = /^[^\t\r\n\f >]+/.exec(context.source); // 匹配未被引号包裹的属性值
      value = match[0]; // 获取属性值
      advanceBy(value.length); // 前进到属性值之后
    }

