### 9.4. 高级拆包配置

#### 9.4.1. **使用 Rollup 的高级配置**

```javascript
// vite.config.js
export default defineConfig({
  build: {
    rollupOptions: {
      output: {
        manualChunks(id) {
          // 将 node_modules 中的包单独打包
          if (id.includes('node_modules')) {
            if (id.includes('pinia')) {
              return 'vendor-pinia'
            }
            return 'vendor'
          }
          // 将 store 模块单独打包
          if (id.includes('/stores/modules/')) {
            const module = id.split('/stores/modules/')[1].split('/')[0]
            return `store-${module}`
          }
        }
      }
    }
  }
})
