## 7. 分支切换问题

即使用**三元符号**时，如何避免不必要的执行？

如下代码：

```js
effect(() => {
  console.log('effect run')
  document.body.innerText = obj.ok ? obj.text : 'not'
})
```

根据上面，我们知道关系如下：

- obj
	- ok
	- fn
- text
	- fn

所以，当 `text` 值改变时，必然会导致 `fn` 重新执行 
- 但其实当`ok` 为 `false` 时，无论 `text` 如何变化，我们不希望 `fn` 重新执行。如何解决呢？

>  解决方案是 **每次副作用函数执行之前，清除上一次建立的关系**。

重新设计结构，`effect.deps` 用来存储 `所有与该副作用函数相关的依赖集合` ，如下代码：

```js
// 用一个全局变量存储当前激活的 effect 函数
let activeEffect
function effect(fn) {
  const effectFn = () => {
    cleanup(effectFn)
    // 当调用 effect 注册副作用函数时，将副作用函数复制给 activeEffect
    activeEffect = effectFn
    fn()
  }
  // activeEffect.deps 用来存储所有与该副作用函数相关的依赖集合
  effectFn.deps = []
  // 执行副作用函数
  effectFn()
}

// 每次都会清除
function cleanup(effectFn) {
  for (let i = 0; i < effectFn.deps.length; i++) {
    const deps = effectFn.deps[i]
    deps.delete(effectFn)
  }
  effectFn.deps.length = 0
}
```

下面看 `trigger` 函数：

```js
function trigger(target, key) {
  const depsMap = bucket.get(target)
  if (!depsMap) return
  const effects = depsMap.get(key);
  // here ，这里出现无限循环
  effects && effects.forEach(effectFn => effectFn())
}
```

但是，上面的代码会出现无限循环，原因类似于下面的代码：

```js
const set = new Set([1])
set.forEach(item => {
  set.delete(1)
  set.add(1)
  console.log(999)
})
```

![|560](https://od-1310531898.cos.ap-beijing.myqcloud.com/202304081406196.png)

解决方案：**新的变量** `newSet`

```js
const set = new Set([1])
const newSet = new Set(set)
newSet.forEach(item => {
  set.delete(1)
  set.add(1)
  console.log(999)
})
```

所以最终 `trigger` 代码：创建`新的变量` `effectsToRun`

```js
function trigger(target, key) {
  const depsMap = bucket.get(target)
  if (!depsMap) return
  const effects = depsMap.get(key)

  const effectsToRun = new Set()
  effects && effects.forEach(effectFn => effectsToRun.add(effectFn))
  effectsToRun.forEach(effectFn => effectFn())
  // effects && effects.forEach(effectFn => effectFn())
}
```

## 8. Effect 函数嵌套的场景

### 8.1. 先说说为什么要支持嵌套

因为 `jsx` 天然需要支持嵌套，如下代码：

```js
const Foo = {
    render() {
        return h('div', 'foo')
    }
}

const Bar = {
    render() {
        // 引用 Foo
        return h(Foo, 'bar')
    }
}
```

### 8.2. 现有 `effect` 函数不支持嵌套

如下代码：

```js hl:3
let temp1, temp2

// 嵌套 effect 里面还有 effect 函数
effect(function effectFn1() {
  console.log('1')
  effect(function effectFn2() {
    console.log('2')
    temp2 = obj.bar
  })
  temp1 = obj.foo
})

// obj.foo之前的值为 true
setTimeout(() => {
    obj.foo = false
}, 5000);
```

我们修改 `obj.foo` , 预期是：

- 输出 `1 2 1` , 因为 obj.foo 修改导致 `fn1` 的执行，打印 `1`，`fn2` 嵌套在 `fn1` 里，所以还会执行`fn2` 打印出 `2`，5s 后，值`obj.foo`改变了，导致 `fn1` 执行，打印出 `2`

但实际上是 `1 2 2`

原因是：发生嵌套时，内层激活的 `activeEffect` 会覆盖`外层的副作用函数`，所以最终执行的都是`内层副作用函数`

### 8.3. 解决思路：副作用函数栈 `efectStack`

如下代码：

```js
// 用一个全局变量存储当前激活的 effect 函数
let activeEffect
// effect 栈
const effectStack = []
function effect(fn) {
  const effectFn = () => {
    cleanup(effectFn)
    // 当调用 effect 注册副作用函数时，将副作用函数复制给 activeEffect
    activeEffect = effectFn
    // 在调用副作用函数之前将当前副作用函数压栈
    effectStack.push(effectFn)
    fn()
    // 在当前副作用函数执行完毕后，将当前副作用函数弹出栈
    // 并还原 activeEffect 为之前的值
    effectStack.pop()
    activeEffect = effectStack[effectStack.length - 1]
  }
  // activeEffect.deps 用来存储所有与该副作用函数相关的依赖集合
  effectFn.deps = []
  // 执行副作用函数
  effectFn()
}
```

## 9. 新的问题：无限递归循环

如下代码，会引起 `栈溢出`

```js
effect(() => {
    obj.foo++;
})
```

因为 `obj.foo 同时读取和设置` ，从而导致无限递归循环。

因为读取和操作是在同一个副作用函数中，进行的。所以可以增加`守卫条件`： **trigger 触发的副作用函数和当前执行的副作用函数，是一个函数，则不执行。**

```js hl:7,6
function trigger(target, key) {
  const depsMap = bucket.get(target)
  if (!depsMap) return
  const effects = depsMap.get(key)
  const effectsToRun = new Set()
  effects && effects.forEach(effectFn => {
    // 守卫条件
    if (effectFn !== activeEffect) {
      effectsToRun.add(effectFn)
    }
  })
  effectsToRun.forEach(effectFn => effectFn())
}
```

## 10. 响应式系统的调度（Scheduler）

所谓`调度`，即 `trigger` 重新触发副作用函数时，能够决定执行的`时机`，`次数`等`自定义行为`。

### 10.1. 例子 1 ：控制执行顺序

以下执行顺序是：`1 ，2 ，end...`

```js
const data = {foo: 1};
const obj = new Proxy(data, {});

effect(() => {
    console.log(obj.foo);
})

obj.foo++;
console.log('end...');
// ::::顺序是：1 ，2 ，end... 
```

如果我们希望顺序变成了：`1 ，end... ，2` 呢？？？

**解法方法是**：
- 给 `effect` 函数添加一个 `options` 参数
	- 即 给在批量执行副作用函数的地方，即 trigger 函数中，添加特定的判断，即调度逻辑，如下代码

```js hl:13,15
function trigger(target, key) {
  const depsMap = bucket.get(target)
  if (!depsMap) return
  const effects = depsMap.get(key)

  const effectsToRun = new Set()
  effects && effects.forEach(effectFn => {
    if (effectFn !== activeEffect) {
      effectsToRun.add(effectFn)
    }
  })
  effectsToRun.forEach(effectFn => {
      // ::::新增代码::::
    if (effectFn.options.scheduler) {
      effectFn.options.scheduler(effectFn)
    } else {
      effectFn()
    }
  })
}
```

修改上面例子代码如下：

> **options 的 scheduler 选项是一个函数**


```js hl:9
const data = {foo: 1};
const obj = new Proxy(data, {});

effect(
    () => {
        console.log(obj.foo);
    },
    {
        scheduler: (fn) => {
            setTimeout(fn, 0);
        }
    }
);

obj.foo++;
console.log('end...');

// ::::顺序就可以变成 1 ，end... ，2
```

### 10.2. 示例 2：合并操作

如下代码

```js
const data = {foo: 1};
const obj = new Proxy(data, {});

effect(
    () => {
        console.log(obj.foo);
    }
);

obj.foo++;
obj.foo++;
obj.foo++;
obj.foo++;

// ::::顺序： 1 2 3 4 5 
```

如果我只打印 `初始值` 和 `最终值`呢？

>  其实就有点类似于 **React 中的 setState 多次或者 Vue 中的连续改变响应式数据。**

#### 10.2.1. 微任务队列

所以，关键是 需要 **实现一个微任务队列，并去重，并且如何保证一个微任务队列里，只执行一次**，如下代码：

```js hl:12,4,1,22
// 任务队列，使用 Set 方便去重
const jobQueue = new Set()
// 标识是否正在刷新微任务队列，
// 如果正在刷新，则不再执行 flushJob，所以一个事件循环中只会执行一次 flushJob
let isFlushing = false
// 利用 promise ，保证 flushJob 在一个事件循环中只执行一次
function flushJob() {
  if (isFlushing) return
  isFlushing = true;
  // 将一个函数添加到微任务队列中
  Promise.resolve().then(() => {
    // 这个时候，取出来的 job 是已经去重过的了，所以不会重复执行了
    jobQueue.forEach(job => job())
  }).finally(() => {
    isFlushing = false
  })
}

effect(() => {
  console.log(obj.foo)
}, {
  // 使用 scheduler 选项，去重任务后，再刷新执行微任务队列的函数
  scheduler(fn) {
    // 使用 Set 来去重
    jobQueue.add(fn);
    // 刷新微任务队列
    flushJob()
  }
})
```

