## 2. 先看看 effect 函数的完整定义、参数、返回值

### 2.1. 完整参数说明

```typescript hl:22
import { effect, reactive } from 'vue'

// 创建响应式对象
const state = reactive({
  count: 0
})

// effect 的完整使用示例
const runner = effect(
  // 第一个参数：效果函数
  () => {
    console.log('count is:', state.count)
    return state.count // 可以有返回值
  },

  // 第二个参数：配置选项
  {
    // 是否延迟执行，默认 false
    lazy: false,

    // 调度器函数
    scheduler: (run) => {
      console.log('scheduler called')
      run()
    },

    // 效果作用域
    scope: undefined,

