class QueueScheduler {
  queue = []
  flushing = false

  add(run) {
    this.queue.push(run)
    this.flush()
  }

  flush() {
    if (this.flushing) return
    this.flushing = true

    Promise.resolve().then(() => {
      while (this.queue.length) {
        const run = this.queue.shift()
        run()
      }
      this.flushing = false
    })
  }
}

const scheduler = new QueueScheduler()

