function onRenderCallback(
  id, // 发生提交的 Profiler 树的 "id"
  phase, // "mount" （首次渲染）或 "update" （重新渲染）
  actualDuration, // 本次更新在渲染完成之前耗费的时间
  baseDuration, // 估计不使用 memoization 的情况下渲染整颗子树需要的时间
