## 4. 自定义异步组件实现

如果需要更细粒度的控制，可以自己实现异步组件：

### 4.1. 基于 Class 组件的实现

```jsx hl:13
// 1. 基于 Class 组件的实现
class AsyncComponent extends React.Component {
  state = {
    Component: null
  };

  componentDidMount() {
    this.loadComponent();
  }

  loadComponent = async () => {
    const { loader } = this.props;
    const Component = await loader();
    this.setState({ Component });
  };

  render() {
    const { Component } = this.state;
    const { fallback, ...props } = this.props;

    return Component ? <Component {...props} /> : fallback;
  }
}

// 使用方式
const AsyncHome = props => (
  <AsyncComponent
    loader={() => import('./Home')}
    fallback={<div>Loading...</div>}
    {...props}
  />
);

```

### 4.2. 基于 Hooks 的实现

```jsx

// 2. 基于 Hooks 的实现
function useAsync(loader) {
  const [Component, setComponent] = React.useState(null);

  React.useEffect(() => {
    loader().then(comp => {
      setComponent(comp.default || comp);
    });
  }, [loader]);

  return Component;
}

function AsyncComponent({ loader, fallback, ...props }) {
  const Component = useAsync(loader);
  return Component ? <Component {...props} /> : fallback;
}
```

## 5. 错误处理和重试机制

### 5.1. 使用 Error Boundary

```jsx hl:5
// 1. 使用 Error Boundary
class ErrorBoundary extends React.Component {
  state = { hasError: false };

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    console.error('Error:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return <div>Something went wrong!</div>;
    }
    return this.props.children;
  }
}

// 使用
function App() {
  return (
    <ErrorBoundary>
      <Suspense fallback={<div>Loading...</div>}>
        <LazyComponent />
      </Suspense>
    </ErrorBoundary>
  );
}

```

### 5.2. 带重试机制的异步组件

```javascript

// 2. 带重试机制的异步组件
function RetryableAsyncComponent({ loader, maxRetries = 3, ...props }) {
  const [error, setError] = React.useState(null);
  const [retries, setRetries] = React.useState(0);
  const [Component, setComponent] = React.useState(null);

  const loadComponent = async () => {
    try {
      const comp = await loader();
      setComponent(comp.default || comp);
      setError(null);
    } catch (err) {
      setError(err);
      if (retries < maxRetries) {
        setTimeout(() => {
          setRetries(r => r + 1);
          loadComponent(); // 递归调用
        }, Math.pow(2, retries) * 1000); // 指数退避
      }
    }
  };

  React.useEffect(() => {
    loadComponent();
  }, []);

  if (error && retries >= maxRetries) {
    return <div>Failed to load component after {maxRetries} retries</div>;
  }

  return Component ? <Component {...props} /> : <div>Loading...</div>;
}
```

### 5.3. 最简单的重试机制

```javascript
function RetryableComponent({ retries = 3 }) {
  const [retry, setRetry] = useState(0);

  return (
    <ErrorBoundary
      onError={() => {
        if (retry < retries) {
          setRetry(r => r + 1);
        }
      }}
    >
      <Suspense fallback={<Loading />}>
        <LazyComponent key={retry} />
      </Suspense>
    </ErrorBoundary>
  );
}

```

