## 12. 选择建议

对于小型项目，可能使用 React 的 Context API 或其他更轻量级的状态管理方案会更合适。

## 13. 总结

1. Redux 是状态管理库，也是一个架构
2. Redux 与 React 无关，但它是为了解决 React 组件中状态无法共享而出的一种解决方案
3. 单纯的 Redux 只是一个状态机， store 中存放了所有的状态 state，要想改变里面的状态 state，只能 dispatch 一个动作
4. 发出去的 action 需要用 reducer 来处理，传入 state 和 action，返回新的 state
5. subscribe 方法可以注册回调方法，当 dispatch action 的时候会执行里面的回调
6. Redux 其实是一个`发布订阅模式`
7. Redux 支持 `enhancer`，enhancer 其实就是一个装饰器函数，传入当前的 createStore，返回一个增强的 createStore
8. Redux 使用 `applyMiddleware` 函数支持中间件，它的返回值其实就是一个 enhancer
9. Redux 的中间件也是一个装饰器模式，传入当前的 dispatch，返回一个增强了的 dispatch
10. 单纯的 Redux 是没有 View 层的

## 14. Redux 处理异步接口有多种方案

### 14.1. Redux Thunk

最基础且使用广泛的异步处理方案。

#### 14.1.1. 基本设置

```javascript
// store.js
import { createStore, applyMiddleware } from 'redux';
import thunk from 'redux-thunk';

const store = createStore(rootReducer, applyMiddleware(thunk));
```

#### 14.1.2. 使用示例

```javascript
// userActions.js
const fetchUserRequest = () => ({ type: 'FETCH_USER_REQUEST' });
const fetchUserSuccess = (user) => ({ type: 'FETCH_USER_SUCCESS', payload: user });
const fetchUserFailure = (error) => ({ type: 'FETCH_USER_FAILURE', payload: error });

// Thunk action creator
export const fetchUser = (userId) => {
  return async (dispatch, getState) => {
    try {
      dispatch(fetchUserRequest());
      const response = await fetch(`/api/users/${userId}`);
      const data = await response.json();
      dispatch(fetchUserSuccess(data));
    } catch (error) {
      dispatch(fetchUserFailure(error.message));
    }
  };
};

// userReducer.js
const initialState = {
  loading: false,
  user: null,
  error: null
};

const userReducer = (state = initialState, action) => {
  switch (action.type) {
    case 'FETCH_USER_REQUEST':
      return { ...state, loading: true };
    case 'FETCH_USER_SUCCESS':
      return { loading: false, user: action.payload, error: null };
    case 'FETCH_USER_FAILURE':
      return { loading: false, user: null, error: action.payload };
    default:
      return state;
  }
};
```

#### 14.1.3. 组件中使用

```javascript
import { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetchUser } from './userActions';

function UserProfile({ userId }) {
  const dispatch = useDispatch();
  const { user, loading, error } = useSelector(state => state.user);

  useEffect(() => {
    dispatch(fetchUser(userId));
  }, [dispatch, userId]);

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;
  if (!user) return null;

  return <div>{user.name}</div>;
}
```

### 14.2. Redux Saga

更强大的异步处理方案，使用 Generator 函数处理复杂的异步流程。

#### 14.2.1. 基本设置

```javascript
// store.js
import { createStore, applyMiddleware } from 'redux';
import createSagaMiddleware from 'redux-saga';
import rootSaga from './sagas';

const sagaMiddleware = createSagaMiddleware();
const store = createStore(rootReducer, applyMiddleware(sagaMiddleware));
sagaMiddleware.run(rootSaga);
```

#### 14.2.2. 使用示例

```javascript
// userSaga.js
import { call, put, takeLatest } from 'redux-saga/effects';

function* fetchUser(action) {
  try {
    yield put({ type: 'FETCH_USER_REQUEST' });
    const response = yield call(fetch, `/api/users/${action.payload}`);
    const data = yield call([response, 'json']);
    yield put({ type: 'FETCH_USER_SUCCESS', payload: data });
  } catch (error) {
    yield put({ type: 'FETCH_USER_FAILURE', payload: error.message });
  }
}

export function* userSaga() {
  yield takeLatest('FETCH_USER', fetchUser);
}

// rootSaga.js
import { all } from 'redux-saga/effects';
import { userSaga } from './userSaga';

export default function* rootSaga() {
  yield all([
    userSaga(),
  ]);
}
```

#### 14.2.3. 组件中使用

```javascript
function UserProfile({ userId }) {
  const dispatch = useDispatch();
  const { user, loading, error } = useSelector(state => state.user);

  useEffect(() => {
    dispatch({ type: 'FETCH_USER', payload: userId });
  }, [dispatch, userId]);

  // 渲染逻辑...
}
```

### 14.3. Redux Toolkit (推荐)

Redux 官方推荐的工具集，简化了 Redux 的使用，内置了 Thunk 中间件。

#### 14.3.1. 基本设置

```javascript
// store.js
import { configureStore } from '@reduxjs/toolkit';
import userReducer from './userSlice';

export const store = configureStore({
  reducer: {
    user: userReducer,
  },
});
```

#### 14.3.2. 使用示例

```javascript
// userSlice.js
import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';

export const fetchUser = createAsyncThunk(
  'user/fetchUser',
  async (userId, { rejectWithValue }) => {
    try {
      const response = await fetch(`/api/users/${userId}`);
      const data = await response.json();
      return data;
    } catch (error) {
      return rejectWithValue(error.message);
    }
  }
);

const userSlice = createSlice({
  name: 'user',
  initialState: {
    loading: false,
    user: null,
    error: null,
  },
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(fetchUser.pending, (state) => {
        state.loading = true;
      })
      .addCase(fetchUser.fulfilled, (state, action) => {
        state.loading = false;
        state.user = action.payload;
        state.error = null;
      })
      .addCase(fetchUser.rejected, (state, action) => {
        state.loading = false;
        state.user = null;
        state.error = action.payload;
      });
  },
});

export default userSlice.reducer;
```

#### 14.3.3. 组件中使用

```javascript
import { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetchUser } from './userSlice';

function UserProfile({ userId }) {
  const dispatch = useDispatch();
  const { user, loading, error } = useSelector(state => state.user);

  useEffect(() => {
    dispatch(fetchUser(userId));
  }, [dispatch, userId]);

  // 渲染逻辑...
}
```

### 14.4. 最佳实践建议

1. **选择合适的方案**
   - 简单项目：Redux Toolkit
   - 复杂异步流程：Redux Saga
   - 特殊需求：考虑 Redux Observable

2. **错误处理**
```javascript
// 统一的错误处理
const handleApiError = (error) => {
  if (error.response?.status === 401) {
    // 处理未授权
    dispatch(logout());
  }
  return error.message;
};

// 在异步 action 中使用
export const fetchUser = createAsyncThunk(
  'user/fetchUser',
  async (userId, { rejectWithValue }) => {
    try {
      const response = await fetch(`/api/users/${userId}`);
      const data = await response.json();
      return data;
    } catch (error) {
      return rejectWithValue(handleApiError(error));
    }
  }
);
```

3. **Loading 状态管理**
```javascript
// 创建通用的 loading selector
const createLoadingSelector = (actions) => (state) => 
  actions.some(action => state.loading[action]);

// 使用
const isLoading = useSelector(createLoadingSelector(['FETCH_USER', 'FETCH_POSTS']));
```

4. **请求缓存**
```javascript
// 缓存管理
const userSlice = createSlice({
  name: 'user',
  initialState: {
    cache: {},
    ttl: 5 * 60 * 1000, // 5分钟缓存
  },
  reducers: {
    updateCache: (state, action) => {
      state.cache[action.payload.id] = {
        data: action.payload.data,
        timestamp: Date.now(),
      };
    },
  },
});

// 使用缓存
export const fetchUserWithCache = createAsyncThunk(
  'user/fetchWithCache',
  async (userId, { getState, dispatch }) => {
    const state = getState();
    const cached = state.user.cache[userId];

    if (cached && Date.now() - cached.timestamp < state.user.ttl) {
      return cached.data;
    }

    const response = await fetch(`/api/users/${userId}`);
    const data = await response.json();
    dispatch(userSlice.actions.updateCache({ id: userId, data }));
    return data;
  }
);
```

5. **取消请求**
```javascript
// Redux Toolkit 方式
export const fetchUser = createAsyncThunk(
  'user/fetchUser',
  async (userId, { signal }) => {
    const response = await fetch(`/api/users/${userId}`, { signal });
    const data = await response.json();
    return data;
  }
);

// 组件中使用
useEffect(() => {
  const promise = dispatch(fetchUser(userId));
  return () => {
    promise.abort();
  };
}, [userId]);
```

6. **TypeScript 支持**
```typescript
// 定义类型
interface User {
  id: number;
  name: string;
}

interface UserState {
  loading: boolean;
  user: User | null;
  error: string | null;
}

// 在 slice 中使用
const userSlice = createSlice({
  name: 'user',
  initialState: {
    loading: false,
    user: null,
    error: null,
  } as UserState,
  // ...
});
```

这些方案各有特点，建议：
- 新项目优先使用 Redux Toolkit
- 需要处理复杂异步流程时考虑 Redux Saga
- 注意做好错误处理和加载状态管理
- 适当使用缓存优化性能
- 考虑请求取消的场景
- 使用 TypeScript 增加类型安全

