import { useState, useEffect } from "react";

const useDebounce = (stateValue, wait) => {
  const [val, setVal] = useState(stateValue);

  useEffect(() => {
    const timer = setTimeout(() => {
      setVal(stateValue);
    }, wait);

    // 清除定时器
    return () => {
      clearTimeout(timer);
    };
