```

#### 4.2.2. 使用 esbuild 的 watch 模式 + 自定义 HMR 实现

```javascript
const esbuild = require('esbuild');
const path = require('path');

// HMR 客户端代码
const hmrClient = `
  const hmr = {
    socket: new WebSocket('ws://localhost:8001'),

    // 存储模块
    modules: new Map(),

    // 注册模块
    register(id, mod) {
      this.modules.set(id, mod);
    },

    // 更新模块
    update(id, newMod) {
      const oldMod = this.modules.get(id);
      if (oldMod) {
        // 保存状态
        const state = oldMod.__hmrState || {};
        // 更新模块
        this.modules.set(id, newMod);
        // 恢复状态
        newMod.__hmrState = state;
        // 触发更新回调
        if (newMod.onHMR) {
          newMod.onHMR(state);
        }
      }
    }
  };

  hmr.socket.onmessage = (event) => {
    const { type, id, code } = JSON.parse(event.data);
    if (type === 'update') {
      // 执行更新的模块代码
      const newMod = eval(code);
      hmr.update(id, newMod);
    }
  };
`;

// 构建配置
const ctx = await esbuild.context({
  entryPoints: ['src/index.js'],
  bundle: true,
  outdir: 'dist',
  sourcemap: true,
  format: 'esm',
  plugins: [{
    name: 'hmr',
    setup(build) {
      // 注入 HMR 客户端代码
      build.onEnd(result => {
        // 处理构建结果
        if (result.errors.length === 0) {
          // 发送更新消息给客户端
          wss.clients.forEach(client => {
            if (client.readyState === WebSocket.OPEN) {
              client.send(JSON.stringify({
                type: 'update',
                modules: result.outputFiles
                  .filter(file => file.path.endsWith('.js'))
                  .map(file => ({
                    id: path.relative('src', file.path),
                    code: file.text
                  }))
              }));
            }
          });
        }
      });
    }
  }]
});

// 启动 watch 模式
await ctx.watch();
```

#### 4.2.3. 结合 Vite 的 HMR 实现

```javascript
const esbuild = require('esbuild');
const { createServer } = require('vite');

async function createDevServer() {
  const vite = await createServer({
    // Vite 配置
    server: {
      middlewareMode: true
    },
    optimizeDeps: {
      // 使用 esbuild 进行依赖预构建
      esbuildOptions: {
        // esbuild 配置
      }
    },
    plugins: [{
      name: 'esbuild-hmr',
      handleHotUpdate({ file, modules }) {
        // 使用 esbuild 构建更新的模块
        const result = await esbuild.build({
          entryPoints: [file],
          write: false,
          bundle: true,
          format: 'esm',
          sourcemap: true
        });

        // 通过 Vite 的 HMR API 发送更新
        modules.forEach(mod => {
          mod.importers.forEach(importer => {
            server.ws.send({
              type: 'update',
              updates: [{
                type: 'js-update',
                timestamp: Date.now(),
                path: mod.url,
                acceptedPath: mod.url
              }]
            });
          });
        });
      }
    }]
  });

  return vite;
}
```

#### 4.2.4. 使用建议

1. **选择合适的方案**
```javascript
// 简单项目：使用方案1
// 中型项目：使用方案2
// 复杂项目：使用方案3或考虑直接使用 Vite
```

2. **性能优化**
```javascript
// 增加缓存机制
const cache = new Map();

async function buildWithCache(filePath) {
  const hash = await getFileHash(filePath);
  if (cache.has(hash)) {
    return cache.get(hash);
  }

  const result = await esbuild.build({/*...*/});
  cache.set(hash, result);
  return result;
}
```

3. **错误处理**
```javascript
