      }));
    }
  });
}
```

这些方案各有优劣：
- 方案1最简单，但功能有限
- 方案2更灵活，但需要更多维护
- 方案3功能最完整，但复杂度较高

选择哪种方案取决于项目需求和复杂度。对于简单项目，方案1足够；对于需要精细控制的项目，可以考虑方案2或3。

### 4.3. esbuild 通过插件实现热更新，性能严重下降

#### 4.3.1. esbuild 的设计理念

esbuild 主要关注构建性能，它的核心功能是：
- 快速的代码打包
- 代码转换
- 代码压缩
- 基础的文件监听（watch）

```javascript
// esbuild 原生的 watch 模式
await esbuild.context({
  entryPoints: ['src/index.js'],
  bundle: true,
  outdir: 'dist',
  watch: true, // 只是简单的重新构建
})
```

#### 4.3.2. 为什么自行实现 HMR 会导致性能下降

1. **额外的文件监听开销**
```javascript
// 需要额外的文件监听系统
const chokidar = require('chokidar');
chokidar.watch('src/**/*').on('change', async (path) => {
  // 每次文件变化都需要：
  // 1. 解析依赖关系
  // 2. 确定更新范围
  // 3. 重新构建受影响的模块
  // 这些都是额外的开销
});
```

2. **模块依赖追踪**
```javascript
// 需要维护模块依赖图
const dependencyGraph = new Map();

function updateModule(path) {
  // 1. 找出所有受影响的模块
  const affectedModules = findAffectedModules(path);

  // 2. 重新构建这些模块
  // 3. 通过 WebSocket 发送更新
  // 这个过程会带来额外的内存和计算开销
}
```

3. **状态管理复杂性**
```javascript
// HMR 需要管理模块的状态
const moduleState = {
  id: 'module-id',
  instances: new Set(),
  acceptCallback: null,
  disposeCallback: null
};

// 这些状态管理会增加内存开销和复杂度
```

