  // 数据上报方法
  private report(data: any): void {
    // 1. Beacon API
    if (navigator.sendBeacon) {
      navigator.sendBeacon(this.config.reportUrl, JSON.stringify(data));
      return;
    }

    // 2. 图片上报
    new Image().src = `${this.config.reportUrl}?data=${encodeURIComponent(JSON.stringify(data))}`;
  }
}
