      // 首次绘制时间
      fpTime: paintMetrics.find(entry => entry.name === 'first-paint')?.startTime,
      // 首次内容绘制时间
      fcpTime: paintMetrics.find(entry => entry.name === 'first-contentful-paint')?.startTime,
      // 资源加载情况
