```typescript
class Reporter {
  private queue: any[] = [];
  private timer: number | null = null;

  constructor(private config: ReporterConfig) {
    this.init();
  }

  private init(): void {
    // 页面卸载前发送
    window.addEventListener('beforeunload', () => {
      this.flush();
    });
  }

  // 添加到队列
  public add(data: any): void {
    this.queue.push({
      ...data,
      timestamp: Date.now()
    });

    // 达到阈值立即发送
    if (this.queue.length >= this.config.maxCache) {
      this.flush();
      return;
    }

    // 定时发送
    if (!this.timer) {
      this.timer = window.setTimeout(() => {
        this.flush();
      }, this.config.delay);
    }
  }

  // 立即发送
  private flush(): void {
    if (this.queue.length === 0) return;

    // 优先使用 Beacon API
    if (navigator.sendBeacon) {
      navigator.sendBeacon(
        this.config.reportUrl,
        JSON.stringify(this.queue)
      );
    } else {
      // 降级方案：图片上报
      const data = encodeURIComponent(JSON.stringify(this.queue));
      new Image().src = `${this.config.reportUrl}?data=${data}`;
    }

    // 清空队列
    this.queue = [];
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
  }
}
```

