class TwoFactorAuth {
  // 生成密钥
  static generateSecret() {
    return speakeasy.generateSecret({
      name: 'MyApp',
      length: 20
    });
  }

  // 生成 TOTP token
  static generateToken(secret) {
    return speakeasy.totp({
      secret: secret.base32,
      encoding: 'base32'
    });
  }

  // 验证 token
  static verifyToken(secret, token) {
    return speakeasy.totp.verify({
      secret: secret.base32,
      encoding: 'base32',
      token: token,
      window: 1
    });
  }
}

// 使用示例
