## 3. 实现一个简易的发布订阅模式

### 3.1. 简易实现

```javascript
class Event {
  constructor(props) {
    // 事件对象, 事件类型, 回调函数队列
    this._events = Object.create(null);
  }

  //订阅事件
  on(type, fn) {
    this._events[type].push(fn);
  }

  // 取消订阅
  off(type, fn) {
    // 找this._events[type]下的fn，remove 它
    // 如果该类型的事件存在，且是数组
    if (Array.isArray(this._events[type])) {
      this._events[type] = this._events[type].filter((event) => {
        return event !== fn && event.origin !== fn;
      });
    }
  }

  // 只订阅一次
  once(type, fn) {
    const only = (...args) => {
      fn.apply(this, args);
      this.off(type, fn);
    };
    only.origin = fn;
    this.add(type, only);
  }

  // 触发事件，type 为事件类型，args 为传递的参数
  emit(type, ...args) {
    // 遍历执行
    if (Array.isArray(this._events[type])) {
      this._events[type].forEach((fn) => {
        fn.apply(this, args);
      });
    }
  }
}
```

### 3.2. 使用

```javascript
// 使用
// 使用示例
const eventEmitter = new Event();

// 订阅事件
function onMessage(data) {
  console.log("Received message:", data);
}
eventEmitter.on("message", onMessage);

// 发布事件
eventEmitter.emit("message", "Hello, World!");

// 取消订阅
eventEmitter.off("message", onMessage);

```

## 4. 简易的观察者模式

```javascript
// 主题类（小宝宝）
class Subject {
  constructor(name) {
    this.name = name;
    this.observers = []; // 存储观察者的数组
    // 小宝宝的状态
    this.state = "开心"; // 难受、开心、生气
  }

  // 添加观察者
  add(observer) {
    this.observers.push(observer);
  }

  // 移除观察者
  remove(observer) {
    const index = this.observers.indexOf(observer);
    if (index > -1) {
      this.observers.splice(index, 1);
    }
  }

  // 通知所有观察者
  notify(data) {
    this.observers.forEach((observer) => observer.update(data));
  }

  // 某些状态变化时调用，用于通知观察者
  setState(state) {
    this.state = state;
    this.notify(this.state);
  }
}

// 观察者类
class Observer {
  constructor(name) {
    this.name = name;
  }

  // 当收到主题的通知时调用
  update(data) {
    console.log(`${this.name} 观察到了小宝宝状态: ${data}`);
  }
}

