    constructor(name, age) {
        this.name = name;
        this.age = age;
    }

    updateName(name) {
        this.name = name;
    }
}

// View
class UserView {
    render(user) {
        return `<div>
            <h1>${user.name}</h1>
            <p>Age: ${user.age}</p>
        </div>`;
    }
}

// Controller
class UserController {
    constructor(model, view) {
        this.model = model;
        this.view = view;
    }

    updateUserName(name) {
        this.model.updateName(name);
        this.refreshView();
    }

    refreshView() {
        const html = this.view.render(this.model);
        document.body.innerHTML = html;
    }
}
```

