## 2. `自顶向下`的暴力递归解法

```typescript
var fib = function (n) {
  if (n === 0) return 0;
  if (n === 1) return 1;
  return fib(n - 1) + fib(n - 2);
};
```

统一尽量使用 dp 函数

```javascript
/**
 * @param {number} n
 * @return {number}
 */
var fib = function (n) {
  function dp(n) {
    if (n === 0) return 0;
    if (n === 1) return 1;
    return dp(n - 1) + dp(n - 2);
  }
  return dp(n);
};

```

算法复杂度，如下图，即`子问题的个数 = O(2^n)`  指数级别，`爆炸`，因为有`重叠子问题` 

![图片](https://832-1310531898.cos.ap-beijing.myqcloud.com/999.%20Obsidian@832/files/20241111.png)

## 3. `自顶向下`的递归解法：带备忘录优化

所谓自顶向下，即 `原问题` 拆解为`子问题` ，`递归`子问题，最终得出`原问题`的答案

```typescript hl:22

// 解决重叠子问题 - 带备忘录的递归解法
var fib = function (n) {
  // 备忘录全初始化为 0
  let memo = new Array(n + 1).fill(0);
  // 注意，这里利用了闭包，把memo传入，能够保证不销毁
  // 进行带备忘录的递归
  return dp(memo, n);
};
// 带着备忘录进行递归
// 两个参数，传入 memo 数组，添加一个参数
var dp = function (memo, n) {
  // base case
  if (n === 0 || n === 1) return n;
  // 已经计算过，不用再计算了
  if (memo[n] !== 0) return memo[n];
  // 否则，重新计算，并且存到memo中
  // 这里利用了闭包，把memo传入
  memo[n] = dp(memo, n - 1) + dp(memo, n - 2);
  return memo[n];
};
```

算法的时间复杂度，即 `子问题的个数 = O(n)` ， 空间复杂度 `O(n)`


更简单的写法是：**dp 函数写到函数体里面，传入参数少一点**

```javascript
/**
 * @param {number} n
 * @return {number}
 */
var fib = function (n) {
  let memo = new Array(n + 1).fill(-1);
  function dp(n) {
    if (n === 0) return 0;
    if (n === 1) return 1;
    if (memo[n] !== -1) return memo[n];
    let res = dp(n - 1) + dp(n - 2);
    memo[n] = res;
    return res;
  }
  return dp(n);
};
```

