- 根据这个 `dp` 函数的定义，那么我们想要的答案就是 `dp(s1, 0, s2, 0)`
- 且 base case 就是 `i == len(s1)` 或 `j == len(s2)` 时，因为这时候 `s1[i..]` 或 `s2[j..]` 就相当于空串了，最长公共子序列的长度显然是 0

```javascript
// 定义：计算 s1[i..] 和 s2[j..] 的最长公共子序列长度
var dp = function(s1, i, s2, j) {
    if (s1.charAt(i) == s2.charAt(j)) {
       // s1[i] 和 s2[j] 必然在 lcs 中， 
       // 加上 s1[i+1..] 和 s2[j+1..] 中的 lcs 长度，就是答案
        return 1 + dp(s1, i + 1, s2, j + 1);
    } else {
        // s1[i] 和 s2[j] 中至少有一个字符不在 lcs 中，
        // 穷举三种情况的结果，取其中的最大结果
        return Math.max(
            // 情况一、s1[i] 不在 lcs 中
            dp(s1, i + 1, s2, j),
            // 情况二、s2[j] 不在 lcs 中
            dp(s1, i, s2, j + 1),
            // 情况三、都不在 lcs 中
            dp(s1, i + 1, s2, j + 1)
        );
    }
};
```

### 1.2. 最终代码

```javascript hl:9,41
var longestCommonSubsequence = function (s1, s2) {
  // 备忘录，消除重叠子问题
  let memo = [];

  // 主函数
  const m = s1.length,
    n = s2.length;
  // 备忘录值为 -1 代表未曾计算
  // 初始化二维数组 memo,直接使用 for吧，别用其他的了
  // 这样不容易出错
  for (let i = 0; i < m; i++) {
    memo[i] = [];
    for (let j = 0; j < n; j++) {
      memo[i][j] = -1;
    }
  }

  // 计算 s1[0..] 和 s2[0..] 的 lcs 长度
  return dp(s1, 0, s2, 0);

  // 定义：计算 s1[i..] 和 s2[j..] 的最长公共子序列长度
  function dp(s1, i, s2, j) {
    // base case：任何一个字符串到头了，返回 0
    // 因为这个时候，lcs 的长度是空字符串
    if (i === s1.length || j === s2.length) {
      return 0;
    }
    // 如果之前计算过，则直接返回备忘录中的答案
    if (memo[i][j] !== -1) {
      return memo[i][j];
    }
    // 根据 s1[i] 和 s2[j] 的情况做选择
    if (s1.charAt(i) === s2.charAt(j)) {
      // s1[i] 和 s2[j] 必然在 lcs 中
      memo[i][j] = 1 + dp(s1, i + 1, s2, j + 1);
    } else {
      // s1[i] 和 s2[j] 至少有一个不在 lcs 中
      memo[i][j] = Math.max(
        dp(s1, i + 1, s2, j), // 情况一： s2[j] 不在 lcs 中
        dp(s1, i, s2, j + 1), // 情况二： s1[i] 不在 lcs 中
        // dp(s1, i + 1, s2, j + 1), // 情况三： 都不在 lcs 中
      );
    }
    return memo[i][j];
  }
};

```

> 情况三可以注释掉，因为被 情况一 和 情况二包含了

