 ## 1. 总结 

### 1.1. 递归解法

- 错误记录：
	- `dp[k + 1, j + 1]` 和 `dp( k+1 , j +1 )`
		- 一个数组，一个函数，区别这么大，老是写错了
- 注意变量：
	- **`i  j  k` 分别代表什么** ，很重要
- dp 函数定义：
	- **`s[i..]` 的子序列中 `t[j..]` 出现的次数为 `dp(i, j)`**


```javascript
var numDistinct = function (s, t) {
  let m = s.length;
  let n = t.length;
  function dp(i, j) {
    // 全部匹配完成，说明匹配成功了，返回 1
    if (j === n) {
      return 1;
    }
    // i 后面的个数 小于 j 后面的个数，说明匹配不到子序列了，直接返回0 即可
    // s[i...] 比 t[j...] 还短
    if (m - i < n - j) {
      return 0;
    }
    let res = 0;
    //  在 s[i..] 中寻找 k，使得 s[k] == t[j]
    for (let k = i; k < m; k++) {
      if (s[k] == t[j]) {
        res += dp(k + 1, j + 1);
      }
    }
    return res;
  }
  return dp(0, 0);
};
```


带备忘录的解法

```javascript hl:13,30
var numDistinct = function (s, t) {
  // s[i..] 的子序列中 t[j..] 出现的次数为 dp(s, i, t, j)
  let m = s.length;
  let n = t.length;

  let memo = new Array(m + 1).fill().map(() => {
    return new Array(n + 1).fill(-1);
  });

  function dp(i, j) {
    if (memo[i][j] !== -1) return memo[i][j];

    // base case
    // 全部匹配完成，说明匹配成功了，返回 1
    if (j === n) {
      return 1;
    }
    // i 后面的个数 小于 j 后面的个数，说明匹配不到子序列了，直接返回0 即可
    // s[i...] 比 t[j...] 还短
    if (m - i < n - j) {
      return 0;
    }
    let res = 0;
    //  在 s[i..] 中寻找 k，使得 s[k] == t[j]
    for (let k = i; k < m; k++) {
      if (s[k] == t[j]) {
        res += dp(k + 1, j + 1);
      }
    }
    memo[i][j] = res;
    return res;
  }
  return dp(0, 0);
};

```

### 1.2. dp 数组迭代解法

> [!todo]
