要点：
- 为了能够正着遍历，`dp[i][j]` 表示 `s[...i]` 的子序列中 `t[...j]` 字符出现的次数
	- 而不是 `s[...j]`
- 动态转移方程

```javascript
/**
 * @param {string} s
 * @param {string} t
 * @return {number}
 */
var numDistinct = function (s, t) {
  const m = s.length;
  const n = t.length;

  // dp[i][j] 表示 s[...i] 的子序列中 t[...j] 字符出现的次数
  // 初始化为0
  const dp = Array(m + 1)
    .fill(0)
    .map(() => Array(n + 1).fill(0));

  // base case
  // 当 t 为空串时，空串是任何字符串的子序列，且只有一种方案
  for (let i = 0; i <= m; i++) {
    dp[i][0] = 1;
  }

  // 填充 DP 数组
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      // ①  当前字符相等时，有两种选择：
      // 1.1 使用当前字符匹配：dp[i-1][j-1]
      // 1.2 不使用当前字符匹配：dp[i-1][j]
      if (s[i - 1] === t[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
      } else {
        //②  当前字符不相等，只能不使用当前字符
        dp[i][j] = dp[i - 1][j];
      }
    }
  }

  return dp[m][n];
};

```

