```javascript hl:8,28,32
var wordBreak = function (s, wordDict) {
  let found = false;
  // 记录搜索过程中的路径
  let track = [];

  // 参数 s 表示当前搜索到的字符串
  // 参数 i 表示当前搜索到 s 中的第 i 个字符
  // 递归函数的定义：对于 s[i..] 这个后缀字符串，从 s[i] 开始搜索 wordDict
  function backtrack(s, i) {
    // base case
    if (found) {
      // 如果已经找到答案，就不要再递归搜索了
      return;
    }
    if (i == s.length) {
      // 整个 s 都被匹配完成，找到一个合法答案
      found = true;
      return;
    }
    // 回溯算法框架
    for (let word of wordDict) {
      // 看看哪个单词能够匹配 s[i..] 的前缀
      let len = word.length;
      // 代表从 i 开始的一个单词，长度为 len，看看是不是等于 word
      let newWord = s.substring(i, i + len);
      if (i + len <= s.length && newWord == word) {
        // 找到一个单词匹配 s[i..i+len)
        // 做选择
        track.push(word);
        // 进入回溯树的下一层，继续匹配 s[i+len..]
        backtrack(s, i + len);
        // 撤销选择
        track.pop();
      }
    }
  }

  backtrack(s, 0);
  return found;
};
