```javascript
/**
 * @param {number[]} numbers
 * @param {number} target
 * @return {number[]}
 */
var twoSum = function (numbers, target) {
  let left = 1;
  let right = numbers.length;

  while (left <= right) {
    let sum = numbers[left - 1] + numbers[right - 1];

    if (sum === target) {
      return [left, right];
    }
    if (sum > target) {
      right--;
    }
    if (sum < target) {
      left++;
    }
  }

  return [-1, -1];
};

```

