var lengthOfLongestSubstring = function (s) {
  let left = 0;
  let right = 0;
  let res = 0;
  let obj = {};
  while (right < s.length) {
    let c = s[right];
    obj[c] = (obj[c] || 0) + 1;
    right++;
    while (obj[c] > 1) {
      let c = s[left];
      obj[c]--;
      left++;
    }
    res = Math.max(res, right - left);
  }
  return res;
};
