    while (right < n) {
        product *= nums[right];
        right++;
        // 缩小窗口
        while (product >= k && left < right) {
            product /= nums[left];
            left++;
        }
        // 现在必然是一个合法的窗口，这个窗口中的子数组个数怎么计算：
