        //  如果 j 从 0 开始，会把对称线左下方的元素也交换了，即相当于根本就没有交互
        for (let j = i ; j < n; j++) {
            let temp = matrix[i][j];
            matrix[i][j] = matrix[j][i];
            matrix[j][i] = temp;
        }
    }
    // 然后反转二维矩阵的【每一行】
    for (let row of matrix) {
        reverse(row);
        // 或者 
