/**
 * @param {number[][]} matrix
 * @return {number[][]}
 */
var transpose = function (matrix) {
  let m = matrix.length;
  let n = matrix[0].length;
  // 注意 1：如何初始化，注意对象的引用问题
  // 注意 2：m 和 n 需要反过来
  let res = new Array(n).fill().map(() => {
