```javascript
var NumMatrix = function (matrix) {
    let m = matrix.length;
    let n = matrix[0].length;
    let preSum = new Array(m + 1).fill(0).map(() => {
        return new Array(n + 1).fill(0);
    });
    for (let i = 1; i < m + 1; i++) {
        for (let j = 1; j < n + 1; j++) {
            // 矩阵 [0, 0, i, j] 的元素和
            preSum[i][j] =
                preSum[i - 1][j] +
                preSum[i][j - 1] +
                matrix[i - 1][j - 1] -
                preSum[i - 1][j - 1];
        }
    }
    this.preSum = preSum;
};
NumMatrix.prototype.sumRegion = function (x1, y1, x2, y2) {
    return (
        this.preSum[x2 + 1][y2 + 1] -
        this.preSum[x1][y2 + 1] -
        this.preSum[x2 + 1][y1] +
        this.preSum[x1][y1]
    );
};
