var removeNthFromEnd = function (head, n) {
  let fast = head;
  let d = new ListNode(-1);
  d.next = head;
  let slow = d;
  // 快指针先走 n 步
  for (let i = 0; i < n; i++) {
    fast = fast.next;
  }
