  // 并且慢指针也跟着走，快指针走到头时，慢指针正好指向倒数第 n 个节点
  while (fast) {
    fast = fast.next;
    slow = slow.next;
  }
  // 删除 slow 指向的节点
  // show = slow.next.next;  // 错误
  slow.next = slow.next.next; // 正确
  return d.next;
};
