    // ::::base case 这是递归的基本情况，也是递归结束的标志
    // 基本情况：如果当前节点为空，直接返回null
    if (root === null) {
        return null;
    }

    // ::::前序位置
    // :::: 对于非空节点，我们递归地调用invertTree函数来翻转当前节点的左子树和右子树。
