    // 分解问题：递归地翻转左子树和右子树
    let left = invertTree(root.left);
    let right = invertTree(root.right);
    // ::::后序位置
    // 将翻转后的左子树和右子树交换
    root.left = right;
    root.right = left;

    // 返回翻转后的根节点
    return root;
};

