```javascript

/**
 * @param {TreeNode} root
 * @return {number[]}
 */
var inorderTraversal = function(root) {
    // ::::返回的结果
    const res = [];

    // ::::::::辅助栈
    const stack = [];

    // ::::::::迭代
    while (root || stack.length) {

        // :::::左节点全部入栈,直到没有左节点
        while (root) {
            stack.push(root);
            root = root.left;
        }

        /*************************************************
         * ::::::::中序位置,只有在弹出栈顶元素的时候才会访问
         ************************************************/
        // :::::弹出栈顶元素
        root = stack.pop();
        res.push(root.val);

        // :::::右节点
        root = root.right;
    }
    return res;
};

```

> - 只有`中序位置` 是确定的，其他没试过
> - 左侧节点，需要全部入栈，然后才是根节点，然后再试右节点，这里都使用一个变量 `root` 来维护，标识当前遍历的 `子节点的根节点`

