## 二叉树 DFS（前中后序遍历）→ 多叉树的 DFS（前后序）

### 二叉树的遍历框架

```javascript
// 二叉树的遍历框架
var traverse = function(root) {
    if (root === null) {
        return;
    }
    // 前序位置
    traverse(root.left);
    // 中序位置
    traverse(root.right);
    // 后序位置
};
```

### N 叉树的遍历框架

```javascript
// N 叉树的遍历框架
var traverse = function(root) {
    if (root === null) {
        return;
    }
    // 前序位置
    for (var i = 0; i < root.children.length; i++) {
        traverse(root.children[i]);
    }
    // 后序位置
};
```

