## 删除链表的最后一个节点

```javascript
/**
 * @description 删除链表的最后一个节点
 * @param {ListNode} head
 * */
function removeLast(head) {
    if (head == null) {
        // ::::返回
        return null;
    }
    if (head.next == null) {
        // ::::返回
        return null;
    }
    let p = head;
    // ::::::::找到倒数第二个节点
    while (p.next.next) {
        p = p.next;
    }
    // ::::::::删除最后一个节点
    p.next = null;
    // ::::::::返回头节点
    return head;
}
```

