        return find(root, p, q);
        function find(root, p, q) {
            if (!root) return null;
            if (root.val === p || root.val === q) return root;
            let left = find(root.left, p, q);
            let right = find(root.right, p, q);
            if (left && right) return root;
            return left || right || null;
        }
    }
};
```

