```javascript
var diameterOfBinaryTree = function (root) {
  let res = 0;
  function maxDepth(root) {
    if (!root) return 0;
    let l = maxDepth(root.left);
    let r = maxDepth(root.right);
    res = Math.max(res, l + r);
    return 1 + Math.max(l, r);
  }
  maxDepth(root);
  return res;
};

```

