var checkEquivalence = function(root1, root2) {
    // 获取所有叶子节点值的和
    const getSum = (root) => {
        // 如果是叶子节点（数字节点）
        if (!root.left && !root.right) {
            return Number(root.val);
        }
        // 如果是操作符节点（+），递归计算左右子树的和
        let sum = 0;
        if (root.left) {
            sum += getSum(root.left);
