function dfs(head, root) {
    // 如果链表已经匹配完，返回true
    if (!head) return true;
    // 如果树节点为空但链表还没匹配完，返回false
    if (!root) return false;
    // 如果当前值不匹配，返回false
    if (root.val !== head.val) return false;
    // 继续匹配链表的下一个节点，可以选择树的左子节点或右子节点
    return dfs(head.next, root.left) || dfs(head.next, root.right);
}
