    // 如果 B 为空，说明 B 已经遍历完了，返回 true
    if (!B) return true;
    // 如果 A 为空，而 B 不为空，返回 false
    if (!A) return false;
    // 如果当前节点的值不相等，返回 false
    if (A.val !== B.val) return false;
    // 递归判断左右子树是否相同
    return isSame(A.left, B.left) && isSame(A.right, B.right);
