var findLeaves = function (root) {
    const res = [];
    // 返回：节点的高度
    function getHeight(node) {
        // 空节点的高度定义为 -1
        if (!node) return -1;
        const left = getHeight(node.left);
        const right = getHeight(node.right);
        // 当前节点的高度 = 左右子树高度的最大值 + 1
        const height = Math.max(left, right) + 1;
        if (!res[height]) {
            res[height] = [];
        }
        res[height].push(node.val);
        return height;
    }
    getHeight(root);
    return res;
};
```

