```javascript
var BSTIterator = function (root) {
    // 模拟递归栈
    let stk = [];
    // 左侧树枝一撸到底
    var pushLeftBranch = function (p) {
        while (p != null) {
            stk.push(p);
            p = p.left;
        }
    };
    pushLeftBranch(root);
    this.next = function () {
        let p = stk.pop();
        pushLeftBranch(p.right);
        return p.val;
    };
    this.hasNext = function () {
        return stk.length > 0;
    };
};
```

