## 代码

```javascript hl:5
var bstToGst = function (root) {
  let sum = 0;
  function traverse(root) {
    if (!root) return;
    // 先把右节点遍历完
    traverse(root.right);
    sum += root.val;
    root.val = sum;
    traverse(root.left);
  }
  traverse(root);
  return root;
};

```

