	- ① 当前差值小于已知最小差值
	- ② 差值相等时，选择较小的值

```javascript hl:7,12
var closestValue = function (root, target) {
    let res = root.val;
    let gap = Infinity;
    function traverse(root) {
        if (!root) return;
        let abs = Math.abs(root.val - target);
        // 1. 当前差值小于已知最小差值
        if (abs < gap) {
            res = root.val;
            gap = abs;
        }
        // 2. 差值相等时，选择较小的值
        if (abs === gap && root.val < res) {
            res = root.val;
        }
        if (target < root.val) {
            traverse(root.left);
        } else {
            traverse(root.right);
        }
    }
    traverse(root);
    return res;
};
```

