        // 记录当前节点，继续往左找更小的可能解
        if (cur.val > p.val) {
            res = cur;
            cur = cur.left;
            // 当前节点值小于等于目标值，后继一定在右子树
        } else {
            cur = cur.right;
        }
    }
    return res;
