	- 后继在右子树的最左节点
-  情况2：如果没有右子树
	- 向上找第一个"**当前节点是其父节点的左子节点**"的节点

```javascript
var inorderSuccessor = function (node) {
    // 情况1：如果有右子树，后继在右子树的最左节点
    if (node.right) {
        node = node.right;
        while (node.left) {
            node = node.left;
        }
        return node;
    }
    // 情况2：如果没有右子树，向上找第一个"当前节点是其父节点的左子节点"的节点
    while (node.parent && node.parent.right === node) {
        node = node.parent;
    }
    return node.parent;
};
```

