        // root 必然是第二棵 BST 的根节点
        res[1] = root;
        // 第一棵 BST 的根节点需要去左子树寻找
        let left = splitBST(root.left, target);
        res[0] = left[0];
        // 保证 root 的左子树都是大于 target 的
        root.left = left[1];
    }
    return res;
};
