/*
 * @param {TreeNode} root
 * @return {number[][]}
 */
var levelOrder = function (root) {
    // 如果根节点为空，则返回空数组
    if (root === null) return [];
    // 返回的结果
    const res = [];
    // 辅助队列,初始化队列，首先加入根节点
    const q = [root];

    while (q.length) {
        const size = q.length;
        // 用于存储当前层的节点值
        const currentLevel = [];
        for (let i = 0; i < size; i++) {
            // :::::出队列
            const node = q.shift();
            currentLevel.push(node.val);
            // :::::左节点先入队列
            if (node.left) {
                q.push(node.left);
            }
            // :::::右节点后入队列
            if (node.right) {
                q.push(node.right);
            }
        }
        res.push(currentLevel);
    }
    return res;
};

```

## 遍历的思路

```javascript
// DFS 思路
var levelTraverse = function(){
    res = [];
    const traverse = function(root, depth) {
        if (root === null) {
            return;
        }
        // 前序位置，看看是否已经存储 depth 层的节点了
        if (res.length <= depth) {
            // 第一次进入 depth 层
            res.push([]);
        }
        // 前序位置，在 depth 层添加 root 节点的值
        res[depth].push(root.val);
        traverse(root.left, depth + 1);
        traverse(root.right, depth + 1);
    }
    // root 视为第 0 层
    traverse(root, 0);
    return res;
}
```

