var findOrder = function (numCourses, prerequisites) {
    let n = numCourses;
    let res = [];
    let hasCycle = false;
    let visited = new Array(n).fill(false);
    let onPath = new Array(n).fill(false);
    let graph = buildGraph();
    function traverse(graph, src) {
        if (onPath[src]) {
            hasCycle = true;
        }
        if (visited[src] || hasCycle) {
            return;
        }
        onPath[src] = true;
        visited[src] = true;
        for (let item of graph[src]) {
            traverse(graph, item);
        }
        res.push(src);
        onPath[src] = false;
    }

    for (let i = 0; i < n; i++) {
        traverse(graph, i);
    }
    if (hasCycle) {
        return [];
    }
    return res.reverse();

    function buildGraph() {
        let graph = new Array(n).fill().map(() => []);
        for (let item of prerequisites) {
            let from = item[1];
            let to = item[0];
            graph[from].push(to);
        }
        return graph;
    }
};

