    function traverse(src) {
        if (!res) return;
        visited[src] = true;
        for (let g of graph[src]) {
            if (!visited[g]) {
                color[g] = !color[src];
                traverse(g);
            } else {
                if (color[g] === color[src]) {
                    res = false;
                }
            }
        }
    }
    // 因为图可能不是连通的，需要遍历所有节点
    for (let i = 1; i <= n; i++) {
        // 从 1 开始遍历，因为从 1 开始编号
        if (!visited[i]) {
            traverse(i);
        }
    }
    return res;
};
```

