        for (let i = n - 1; i > sortedIndex; i--) { // 倒着遍历
            if (nums[i] < nums[i - 1]) { // 保证稳定性
                [nums[i], nums[i - 1]] = [nums[i - 1], nums[i]];
            }
        }
        sortedIndex++;
    }
    return nums;
}
