```javascript
var sortArray = function (nums) {
    return sort(nums);

    function sort(nums) {
        let n = nums.length;
        // base cace
        if (n < 2) return nums;
        let left = [];
        let right = [];
        let midIndex = Math.floor(n / 2);
        let mid = nums[midIndex];
        nums.splice(midIndex, 1); // 删除
        for (let num of nums) {
            if (num < mid) {
                left.push(num);
            } else {
                right.push(num);
            }
        }
        // 前序位置
        let leftArr = sort(left);
        let rightArr = sort(right);
        return [...leftArr, mid, ...rightArr];
