## 2. 思路

- 将引用次数**降序**排序
- 从前向后遍历，当**引用次数大于当前索引**时，h 指数加 1 

### 2.1. 代码实现

```javascript
/**
 * @param {number[]} citations
 * @return {number}
 */
var hIndex = function (citations) {
  let res = 0;
  // ① 先排序，降序排序
  citations.sort((a, b) => b - a);
  // ②  从前向后遍历，当**引用次数大于当前索引**时，h 指数加 1 
  for (let i = 0; i < citations.length; i++) {
    //  如果当前引用数大于等于当前下标值，则 h 值为当前下标值
    if (citations[i] >= i + 1) {
      res = i + 1;
      // 否则，直接跳出循环
    } else {
      break;
    }
  }
  return res;
};

```

