var letterCombinations = function (digits) {
    // base case
    if (!digits) return [];
    const mapping = ["", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"];
    let res = [];
    let n = digits.length;
    function backtrack(track, index) {
        if (track.length === n) {
            res.push(track.join(''));
            return;
        }
        let str = mapping[parseInt(digits[index])]
        for (let c of str) {
            track.push(c);
            backtrack(track, index + 1);
            track.pop();
        }
    }
    backtrack([], 0);
    return res;
};
