var numsSameConsecDiff = function (n, k) {
  let res = [];
  function backtrack(track, index) {
    // 当数字长度达到n时
    if (index === n) {
      // 将数组转换为数字并添加到结果中
      res.push(parseInt(track.join("")));
      return;
    }

    for (let i = 0; i <= 9; i++) {
