      // 获取前一个数字
      let prev = index > 0 ? track[index - 1] : -100;
      // 如果是第一个数字，或者与前一个数字差的绝对值等于k
      if (index === 0 || Math.abs(i - prev) === k) {
        track.push(i);
        backtrack(track, index + 1);
        track.pop();
      }
    }
  }

  backtrack([], 0);
  return res;
};

