```javascript hl:7,12
// 二维矩阵遍历框架
var dfs = function (grid, i, j, visited) {
  var m = grid.length,
    n = grid[0].length;

  if (i < 0 || j < 0 || i >= m || j >= n) {
    // 超出索引边界
    return;
  }

  if (visited[i][j]) {
    // 已遍历过 (i, j)
    return;
  }

  // 进入当前节点 (i, j)
  visited[i][j] = true;

  // 进入相邻节点（四叉树）
  // 上
  dfs(grid, i - 1, j, visited);
  // 下
  dfs(grid, i + 1, j, visited);
  // 左
  dfs(grid, i, j - 1, visited);
  // 右
  dfs(grid, i, j + 1, visited);
};

```

