var maxAreaOfIsland = function (grid) {
  let m = grid.length;
  let n = grid[0].length;
  let res = 0;

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 1) {
        res = Math.max(res, dfs(i, j));
      }
    }
  }

  return res;

  function dfs(i, j) {
    // 超出索引边界
    if (i < 0 || j < 0 || i >= m || j >= n) {
      return 0;
    }
    // 已经是海水了
    if (grid[i][j] === 0) {
      return 0;
    }
    grid[i][j] = 0;
    // 访问上下左右的陆地
    return (
      dfs(i + 1, j) + // 下
      dfs(i, j + 1) + // 右
      dfs(i - 1, j) + // 上
      dfs(i, j - 1) + // 左
      1 // 当前格子的面积
    ); 
  }
};
```

## 2. 题目

