function createVocab(tokens) {
  // 去重
  const unique = new Set(tokens);

  // 排序
  const sorted = Array.from(unique).sort();

  // 创建映射
  const vocab = {};
  sorted.forEach((token, i) => {
    vocab[token] = i;
  });

  return vocab;
}

